function request_query(array $u): array {
 [$w,$p]=request_scope($u);if(is_staff($u))$w.=" AND r.status<>'draft'";
 $status=(string)($_GET['status']??'');if(in_array($status,STATUSES,true)){$w.=' AND r.status=?';$p[]=$status;}
 $kind=(string)($_GET['kind']??'');if(in_array($kind,['complaint','permit'],true)){$w.=' AND r.kind=?';$p[]=$kind;}
 $dept=(int)($_GET['department']??0);if(can('requests.scope_all',$u)&&$dept){$w.=' AND r.department_id=?';$p[]=$dept;}
 $q=mb_substr(trim((string)($_GET['q']??'')),0,100);if($q!==''){$w.=' AND (r.subject LIKE ? OR r.reference LIKE ? OR u.name LIKE ?)';$like='%'.str_replace(['\\','%','_'],['\\\\','\\%','\\_'],$q).'%';array_push($p,$like,$like,$like);}
 if(($_GET['overdue']??'')==='1'){$w.=" AND r.status IN ('submitted','in_review','needs_information') AND r.due_at<?";$p[]=now();}
 if(($_GET['mine']??'')==='1'&&is_staff($u)){$w.=' AND r.assigned_to=?';$p[]=$u['id'];}
 return [$w,$p];
}
function requests_page(): void {
 $u=require_user();[$w,$p]=request_query($u);$page=max(1,(int)($_GET['page']??1));$total=(int)value("SELECT COUNT(*) FROM requests r JOIN users u ON u.id=r.user_id WHERE $w",$p);$pages=max(1,(int)ceil($total/15));$page=min($page,$pages);$offset=($page-1)*15;
 $list=rows("SELECT r.*,d.name department_name,u.name citizen_name FROM requests r JOIN departments d ON d.id=r.department_id JOIN users u ON u.id=r.user_id WHERE $w ORDER BY CASE WHEN r.status='needs_information' THEN 0 ELSE 1 END,r.updated_at DESC LIMIT 15 OFFSET $offset",$p);
 page_start(is_staff($u)?'Request workspace':'My requests','Search, filter and follow the requests that matter to you.','requests');?><div class="flex between mb"><p class="small muted"><?=$total?> matching request<?=$total===1?'':'s'?></p><?php if($u['role']==='citizen'):?><a class="btn btn-primary" href="<?=e(url('requests/new'))?>"><?=icon('plus')?> New request</a><?php else:?><div class="flex"><a class="btn btn-outline" href="<?=e(url('requests?mine=1'))?>">Assigned to me</a><a class="btn btn-outline" href="<?=e(url('requests?overdue=1'))?>">Overdue queue</a></div><?php endif;?></div><section class="panel panel-body"><form class="filters" action="<?=e(url('requests'))?>" method="get"><?php field('q','Search',(string)($_GET['q']??''),'search','maxlength="100" placeholder="Reference or subject"');$opts=[''=>'All statuses'];foreach(STATUSES as $s)if($s!=='draft'||!is_staff($u))$opts[$s]=label($s);select_field('status','Status',$opts,(string)($_GET['status']??''));select_field('kind','Type',[''=>'All types','complaint'=>'Complaints','permit'=>'Permits'],(string)($_GET['kind']??''));if(can('requests.scope_all',$u)){$opts=[''=>'All departments'];foreach(rows('SELECT id,name FROM departments ORDER BY name')as $d)$opts[$d['id']]=$d['name'];select_field('department','Department',$opts,(string)($_GET['department']??''));}if(isset($_GET['overdue']))echo '<input type="hidden" name="overdue" value="1">';if(isset($_GET['mine']))echo '<input type="hidden" name="mine" value="1">';?><button class="btn btn-primary" type="submit">Apply filters</button><a class="btn btn-outline" href="<?=e(url('requests'))?>">Clear</a></form><?php request_table($list,is_staff($u));?><div class="pagination"><span>Page <?=$page?> of <?=$pages?></span><?php foreach(['Previous'=>$page-1,'Next'=>$page+1]as $text=>$n)if($n>=1&&$n<=$pages){$query=$_GET;$query['page']=$n;?><a class="btn btn-outline btn-sm" href="<?=e(url('requests?'.http_build_query($query)))?>"><?=e($text)?></a><?php }?></div></section><?php page_end();
}
