 if(!$closed&&$r['status']!=='draft'&&(can('requests.message',$u)||can('requests.internal_notes',$u))){panel_start('Conversation');?><form method="post" enctype="multipart/form-data" action="<?=e(url('requests/'.$id.'/reply'))?>" data-once><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$r['version']?>"><?php textarea_field('message',$r['status']==='needs_information'&&!$staff?'Provide the requested information':'Add a message');file_field();if(can('requests.internal_notes',$u)):?><label class="checkbox"><input name="internal" type="checkbox" value="1"> Internal note — visible to authorised staff only</label><?php endif;?><button class="btn btn-primary" type="submit">Send message</button></form><?php panel_end();}
 if(!$staff&&$r['status']==='draft'):?><section class="panel panel-body"><h3>Ready to submit?</h3><p class="small muted">This draft has not been sent to the department.</p><a class="btn btn-primary" href="<?=e(url('requests/'.$id.'/edit'))?>">Complete draft <?=icon('arrow')?></a></section><?php endif;
 if(!$staff&&can('requests.feedback',$u)&&in_array($r['status'],['approved','resolved','rejected'],true)){panel_start('Service feedback');$f=row('SELECT * FROM feedback WHERE request_id=?',[$id]);if($f):?><p class="small">You rated this service <strong><?=(int)$f['rating']?> out of 5</strong>.</p><p class="prose"><?=e($f['comment'])?></p><?php else:?><form method="post" action="<?=e(url('requests/'.$id.'/feedback'))?>"><?=csrf_field()?><?php select_field('rating','How was your experience?',[''=>'Choose a rating',5=>'5 — Excellent',4=>'4 — Good',3=>'3 — Fair',2=>'2 — Poor',1=>'1 — Very poor'],'','required');textarea_field('comment','Feedback if you wish','',2000,false);?><button class="btn btn-primary" type="submit">Submit feedback</button></form><?php endif;panel_end();}
 ?></div><div class="stack"><?php if($staff&&!$closed&&$r['status']!=='draft'&&(can('requests.review',$u)||can('requests.decide',$u))){panel_start('Review and decision');$allowed=['submitted'=>['in_review'],'in_review'=>['needs_information',$r['kind']==='permit'?'approved':'resolved','rejected'],'needs_information'=>['in_review']];$opts=[];foreach($allowed[$r['status']]??[]as $s)if(can(in_array($s,['approved','resolved','rejected'],true)?'requests.decide':'requests.review',$u))$opts[$s]=label($s);?><form method="post" action="<?=e(url('requests/'.$id.'/status'))?>" data-once><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$r['version']?>"><?php select_field('status','Next status',$opts,'','required');textarea_field('message','Reason or update for the citizen','',5000);?><button class="btn btn-primary" type="submit">Record update</button></form><?php panel_end();}if($staff&&!$closed&&$r['status']!=='draft'&&can('requests.assign',$u)){panel_start('Assignment and routing');?><form method="post" action="<?=e(url('requests/'.$id.'/assign'))?>"><?=csrf_field()?><input type="hidden" name="version" value="<?=(int)$r['version']?>"><?php if(can('requests.reroute',$u)){$opts=[];foreach(rows('SELECT id,name FROM departments ORDER BY name')as $d)$opts[$d['id']]=$d['name'];select_field('department_id','Department',$opts,(string)$r['department_id']);}else echo '<input type="hidden" name="department_id" value="'.(int)$r['department_id'].'">';$opts=[''=>'Unassigned'];foreach(rows("SELECT u.*,d.name department_name FROM users u JOIN departments d ON d.id=u.department_id WHERE u.status='active'".(!can('requests.reroute',$u)?' AND u.department_id='.(int)$u['department_id']:''))as $a)if(can('requests.review',$a))$opts[$a['id']]=$a['name'].' — '.$a['department_name'];select_field('assigned_to','Reviewing officer',$opts,(string)($r['assigned_to']??''));textarea_field('message','Reason for routing change','',1000);?><p class="small muted">Select an officer from the chosen department. Use Unassigned if a suitable officer is not yet available.</p><button class="btn btn-outline" type="submit">Save assignment</button></form><?php panel_end();}
