function download_document(int $id): never {
 $u=require_permission('documents.download');$f=row('SELECT * FROM attachments WHERE id=?',[$id]);if(!$f||($f['visibility']==='internal'&&!can('requests.internal_notes',$u)))abort_page(404,'Document not found.');scoped_request((int)$f['request_id'],$u);$path=ROOT.'/storage/uploads/'.basename($f['stored_name']);if(!is_file($path))abort_page(404,'Document file is unavailable.');audit('document.downloaded',$id);header('Content-Type: '.$f['mime']);header("Content-Disposition: attachment; filename=\"document-".$id.'\"; filename*=UTF-8\'\''.rawurlencode($f['original_name']));header('Content-Length: '.filesize($path));header('X-Download-Options: noopen');readfile($path);exit;
}
function document_page(int $id,string $type): void {
 $u=require_permission('documents.print');$r=scoped_request($id,$u);$permit=$type==='permit';if($permit&&($r['kind']!=='permit'||$r['status']!=='approved'))abort_page(404,'Approval document is not available.');page_start($permit?'Permit approval':'Request receipt','Print this record or save it as a PDF from your browser.','requests');?><div class="actions no-print mb"><button class="btn btn-primary" id="printButton" type="button"><?=icon('download')?> Print / Save PDF</button><a class="btn btn-outline" href="<?=e(url('requests/'.$id))?>">Back to request</a></div><article class="permit-document"><div class="permit-letterhead"><img src="<?=e(url('assets/img/logo.svg'))?>" alt="CivicFlow"><div><strong>CivicFlow</strong><div class="small muted"><?=e($r['department_name'])?></div></div></div><h2><?=$permit?'Permit approval record':'Service request receipt'?></h2><div class="seal"><?=cfg('demo_mode',false)?'Demonstration record · No legal effect':e(setting('organisation_name','Service authority'))?></div><p class="mono"><?=e($r['reference'])?></p><p class="small"><?=$permit?'This document records the approval of the application below in the service workspace.':'This receipt confirms the request has been recorded in the CivicFlow workspace. A receipt is not an approval.'?></p><hr class="divider"><dl class="detail-meta"><?php foreach(['Applicant'=>$r['citizen_name'],'Service'=>$r['service_title'],'Request subject'=>$r['subject'],'Organisation'=>$r['organisation']?:'Not applicable','Location'=>$r['location'],'Status'=>label($r['status']),'Recorded'=>dates($r['created_at'],true),$permit?'Decision date':'Service target'=>dates($permit?$r['closed_at']:$r['due_at'],true)]as $k=>$v):?><div><dt><?=e($k)?></dt><dd><?=e($v)?></dd></div><?php endforeach;?></dl><?php if(!$permit&&$u['role']==='citizen'):?><hr class="divider"><p class="small"><strong>Private tracking code:</strong> <span class="mono"><?=e($r['access_token'])?></span></p><p class="small">Track at <?=e(url('track'))?> using your reference and private code.</p><?php endif;?><div class="verification-strip"><?php if($permit):?>Verify this record at <a href="<?=e(url('verify/'.$r['reference']))?>"><?=e(url('verify/'.$r['reference']))?></a>.<?php else:?>Follow the full request history from your signed-in account.<?php endif;?><p class="mt">Generated <?=e(dates(now(),true))?>. <?=cfg('demo_mode',false)?'Demonstration document only. No legal effect.':'Issued as a digital service record by '.e(setting('organisation_name','the service authority')).'. Applicable conditions and authority are determined by the issuer.'?></p></div></article><?php page_end();
}
