}
function profile_page(): void {
 $u=require_user();page_start('Profile and security','Keep your contact information and account secure.','profile');?><?php if(!$u['email_verified_at']):?><div class="notice mb"><strong>Email verification pending.</strong><p>Verify your email to confirm the address used for account recovery and notifications.</p><form method="post" action="<?=e(url('profile/verify-email'))?>"><?=csrf_field()?><button class="btn btn-outline btn-sm" type="submit">Resend verification email</button></form></div><?php endif;?><div class="grid grid-2"><?php panel_start('Your profile');?><p class="small muted">Email: <?=e($u['email'])?> · Role: <?=e(label($u['role']))?></p><form method="post" action="<?=e(url('profile'))?>"><?=csrf_field()?><?php field('name','Full name',$u['name'],'text','required maxlength="140"');field('phone','Phone number',$u['phone'],'tel','maxlength="25"');?><label class="checkbox"><input type="checkbox" name="notify_email" value="1" <?=$u['notify_email']?'checked':''?>> Receive routine email updates</label><label class="checkbox"><input type="checkbox" name="notify_sms" value="1" <?=$u['notify_sms']?'checked':''?>> Receive routine SMS updates</label><p class="small muted">In-app notifications are always available. External delivery depends on the configured email and SMS channels.</p><button class="btn btn-primary" type="submit">Save profile</button></form><?php panel_end();panel_start('Change password');?><form method="post" action="<?=e(url('profile/password'))?>"><?=csrf_field()?><?php field('current_password','Current password','','password','required autocomplete="current-password"');field('password','New password','','password','required minlength="12" maxlength="72" autocomplete="new-password"');field('password_confirm','Confirm new password','','password','required minlength="12" maxlength="72" autocomplete="new-password"');?><p class="small muted">Use at least 12 characters including letters and numbers. Changing your password signs out other sessions.</p><button class="btn btn-primary" type="submit">Change password</button></form><?php panel_end();?></div><?php page_end();
