function reports_page(): void {
 $u=require_permission('reports.view');[$w,$p]=request_scope($u);$w.=" AND r.status<>'draft'";page_start('Reports and insights','Operational performance across the services you manage.','reports');$tot=(int)value("SELECT COUNT(*) FROM requests r WHERE $w",$p);$done=(int)value("SELECT COUNT(*) FROM requests r WHERE $w AND r.status IN ('approved','resolved')",$p);$late=(int)value("SELECT COUNT(*) FROM requests r WHERE $w AND r.status IN ('submitted','in_review','needs_information') AND r.due_at<?",array_merge($p,[now()]));$avg=value("SELECT AVG(f.rating) FROM feedback f JOIN requests r ON r.id=f.request_id WHERE $w",$p);?><div class="flex between mb"><p class="small muted">Live database totals · All times WAT</p><div class="flex"><?php if(can('reports.export',$u)):?><a class="btn btn-outline" href="<?=e(url('reports/export'))?>"><?=icon('download')?> Export CSV</a><?php endif;?><button id="printButton" type="button" class="btn btn-outline">Print report</button></div></div><div class="grid grid-4"><?php foreach([['Total requests',$tot],['Completed',$done],['Open and overdue',$late],['Average feedback',$avg?number_format((float)$avg,1).' / 5':'No ratings']]as $x):?><div class="metric-card"><span class="metric-label"><?=e($x[0])?></span><div class="metric-value"><?=e($x[1])?></div></div><?php endforeach;?></div><div class="grid grid-2 mt"><?php panel_start('Status distribution');$groups=rows("SELECT r.status,COUNT(*) amount FROM requests r WHERE $w GROUP BY r.status ORDER BY amount DESC",$p);?><div class="chart-rows"><?php foreach($groups as $g):?><div class="chart-row"><label><?=e(label($g['status']))?><span><?=(int)$g['amount']?></span></label><progress value="<?=(int)$g['amount']?>" max="<?=max(1,$tot)?>" aria-label="<?=e(label($g['status']))?>"></progress></div><?php endforeach;?></div><?php if(!$groups)echo '<p class="small muted">No submitted requests yet.</p>';panel_end();panel_start('Service targets');$final=(int)value("SELECT COUNT(*) FROM requests r WHERE $w AND r.closed_at IS NOT NULL AND r.status IN ('approved','resolved','rejected')",$p);$on=(int)value("SELECT COUNT(*) FROM requests r WHERE $w AND r.closed_at IS NOT NULL AND r.status IN ('approved','resolved','rejected') AND r.closed_at<=r.due_at",$p);?><p class="metric-value"><?=$final?round($on/$final*100).'%':'—'?></p><p class="small muted">Closed decisions recorded within the service target.</p><p class="small"><?=$on?> on time out of <?=$final?> decisions. Withdrawn requests are excluded. Reopened complaints use the refreshed target.</p><p class="notice mt">Targets are calendar-hour commitments configured by the responsible department. They do not replace any separately applicable statutory deadline.</p><?php panel_end();?></div><?php panel_start('Department workload');$depts=rows("SELECT d.name,COUNT(*) total,SUM(CASE WHEN r.status IN ('submitted','in_review','needs_information') THEN 1 ELSE 0 END) open_count FROM requests r JOIN departments d ON d.id=r.department_id WHERE $w GROUP BY d.id,d.name ORDER BY total DESC",$p);?><div class="table-responsive"><table class="table"><thead><tr><th>Department</th><th>All requests</th><th>In progress</th></tr></thead><tbody><?php foreach($depts as $d):?><tr><td><?=e($d['name'])?></td><td><?=(int)$d['total']?></td><td><?=(int)$d['open_count']?></td></tr><?php endforeach;?></tbody></table></div><?php panel_end();page_end();
}
function export_requests(): never {
 $u=require_permission('reports.export');[$w,$p]=request_query($u);$list=rows("SELECT r.reference,r.kind,r.subject,u.name citizen_name,d.name department_name,r.status,r.priority,r.created_at,r.due_at,r.closed_at,r.escalated_at FROM requests r JOIN users u ON u.id=r.user_id JOIN departments d ON d.id=r.department_id WHERE $w ORDER BY r.id DESC LIMIT 5000",$p);audit('report.exported',null,['rows'=>count($list)]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="civicflow-requests-'.date('Ymd').'.csv"');$f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");fputcsv($f,['Reference','Type','Subject','Citizen','Department','Status','Priority','Created WAT','Target WAT','Closed WAT','Escalated WAT']);foreach($list as $r){$safe=array_map(fn($v)=>preg_match('/^[\s]*[=+@-]/',(string)$v)?"'".$v:(string)$v,array_values($r));fputcsv($f,$safe);}fclose($f);exit;
}

